RUNNERS = {
    "M": (["forge", "test"], r"^\[FAIL.*\]\s+(\w+)\("),
    # The shared pool: its own test file is enough, and much faster than the whole suite.
    "P": (["forge", "test", "--match-path", "test/shared/*"], r"^\[FAIL.*\]\s+(\w+)\("),
    # The paper exam: its own test file, the way "P" runs only the shared pool's.
    "X": (["forge", "test", "--match-path", "test/exam/*"], r"^\[FAIL.*\]\s+(\w+)\("),
    # A pool its owner runs and the pool of many traders: the tests under test/multi.
    "Y": (["forge", "test", "--match-path", "test/multi/*"], r"^\[FAIL.*\]\s+(\w+)\("),
    # The gate that keeps personal addresses out of this public history, and the list of commits
    # it accepts anyway: its own cases name themselves in the FAIL line.
    "S": (["bash", "scripts/test-identity-check.sh"], r"^FAIL (.+?)(?::|$)"),
    "G": (["spike/.venv/bin/python", "-m", "unittest", "discover", "-s", "gateway/tests", "-t", "."],
          r"^(?:FAIL|ERROR): (\w+) \("),
    "A": (["spike/.venv/bin/python", "-m", "unittest", "discover", "-s", "agents/tests", "-t", "."],
          r"^(?:FAIL|ERROR): (\w+) \("),
    "K": (["spike/.venv/bin/python", "-m", "unittest", "discover", "-s", "ops/tests", "-t", "."],
          r"^(?:FAIL|ERROR): (\w+) \("),
    "J": (["node", "--test", "--test-reporter=tap", *sorted(str(p.relative_to(ROOT)) for p in (ROOT / "app" / "tests").glob("*.test.mjs"))],
          r"^\s*not ok \d+ - (.+?)\s*$"),
    # The shared pool's page: its own test file, the way "P" runs only the shared pool's contract tests.
    "PJ": (["node", "--test", "--test-reporter=tap", "app/tests/shared.test.mjs"], r"^\s*not ok \d+ - (.+?)\s*$"),
    # The page "What happened on chain": its own test file.
    "PE": (["node", "--test", "--test-reporter=tap", "app/tests/evidence.test.mjs"], r"^\s*not ok \d+ - (.+?)\s*$"),
    # A pool's stage 4 in the app: its own test file.
    "PS": (["node", "--test", "--test-reporter=tap", "app/tests/stages.test.mjs"], r"^\s*not ok \d+ - (.+?)\s*$"),
    "PQ": (["node", "--test", "--test-reporter=tap", "app/tests/gentle.test.mjs"], r"^\s*not ok \d+ - (.+?)\s*$"),
    # The Economics page's measured tail against the cascade package: its own test file.
    "PT": (["node", "--test", "--test-reporter=tap", "app/tests/tail.test.mjs"], r"^\s*not ok \d+ - (.+?)\s*$"),
    # The shared pool's keeper: its own test module.
    "PK": (["spike/.venv/bin/python", "-m", "unittest", "ops.tests.test_shared_keeper"], r"^(?:FAIL|ERROR): (\w+) \("),
    # The shared pool's run script: its own test module.
    "PR": (["spike/.venv/bin/python", "-m", "unittest", "ops.tests.test_shared_run"], r"^(?:FAIL|ERROR): (\w+) \("),
    # The stop and the take on Hyperliquid: the gateway's own test module, and the keeper's check of them.
    "PG": (["spike/.venv/bin/python", "-m", "unittest", "gateway.tests.test_protect"], r"^(?:FAIL|ERROR): (\w+) \("),
    "PW": (["spike/.venv/bin/python", "-m", "unittest", "ops.tests.test_keeper_protect"], r"^(?:FAIL|ERROR): (\w+) \("),
    # The levers on the Economics page: their own test file.
    "PL": (["node", "--test", "--test-reporter=tap", "app/tests/levers.test.mjs"], r"^\s*not ok \d+ - (.+?)\s*$"),
    "PF": (["node", "--test", "--test-reporter=tap", "app/tests/platformfees.test.mjs"], r"^\s*not ok \d+ - (.+?)\s*$"),
    "PB": (["node", "--test", "--test-reporter=tap", "app/tests/wallet.test.mjs"], r"^\s*not ok \d+ - (.+?)\s*$"),
    "PC": (["node", "--test", "--test-reporter=tap", "app/tests/deployments.test.mjs"], r"^\s*not ok \d+ - (.+?)\s*$"),
    "PD": (["node", "--test", "--test-reporter=tap", "app/tests/lending.test.mjs"], r"^\s*not ok \d+ - (.+?)\s*$"),
    "PU": (["node", "--test", "--test-reporter=tap", "app/tests/ux.test.mjs"], r"^\s*not ok \d+ - (.+?)\s*$"),
    # Whether an agent can trade a pool through the client: its own test file.
    "PA": (["node", "--test", "--test-reporter=tap", "app/tests/agentcap.test.mjs"], r"^\s*not ok \d+ - (.+?)\s*$"),
    # An investor's withdrawal on HyperCore: its own test file.
    "PV": (["node", "--test", "--test-reporter=tap", "app/tests/withdraw.test.mjs"], r"^\s*not ok \d+ - (.+?)\s*$"),
}


def runner_of(mid: str) -> str:
    """The runner a mutation id names: its two-letter prefix if there is a runner for it, else its first letter."""
    return mid[:2] if mid[:2] in RUNNERS else mid[0]

# A mutation can turn a bounded loop into an endless one; that has to end the run, not hang it.
RUN_TIMEOUT_S = 900


def run_suite(cmd: list[str]) -> subprocess.CompletedProcess:
    """One test run with its own empty bytecode cache. Python trusts a cached .pyc when the
    source's size and modification second match, and a mutation of the same length restored
    within the same second would otherwise keep running as the mutant afterwards."""
    with tempfile.TemporaryDirectory(prefix="mutations-pyc-") as cache:
        env = {**os.environ, "PYTHONPYCACHEPREFIX": cache}
        return subprocess.run(cmd, cwd=ROOT, capture_output=True, text=True, timeout=RUN_TIMEOUT_S, env=env)


def failing_tests(output: str, pattern: str) -> set[str]:
    # Forge: a failure message can contain brackets of its own ("[1.08e8]"), so the pattern
    # takes the last "]" on the line; the test name follows it.
    return set(re.findall(pattern, output, re.M))


def red_tests(cmd: list[str], pattern: str) -> set[str] | None:
    """Names of the red tests, or None if the suite did not run to the end."""
    try:
        proc = run_suite(cmd)
    except subprocess.TimeoutExpired:
        return None
    out = proc.stdout + proc.stderr
    if "Compiler run failed" in out or "Error (" in out or "SyntaxError" in out:
        return None
    return failing_tests(out, pattern)


def baseline(chosen) -> int:
    problems = 0
    for prefix in sorted({runner_of(m[0]) for m in chosen}):
        cmd, pattern = RUNNERS[prefix]
        red = red_tests(cmd, pattern)
        named = {t for m in chosen if runner_of(m[0]) == prefix for t in m[4]}
        if red is None:
            print(f"baseline {prefix}: the suite did not run")
            problems += 1
        elif red & named:
            print(f"baseline {prefix}: already red before any mutation: {sorted(red & named)}")
            problems += 1
    return problems


def _test_names() -> set[str]:
    """Every test a suite would actually run, by name.

    Comment lines go first: a commented-out test still reads as a declaration to a regular
    expression, and a mutation naming a disabled test is as blind as one naming a deleted one.
    """
    names: set[str] = set()
    for d in ("test", "ops/tests", "gateway/tests", "agents/tests"):
        for f in (ROOT / d).rglob("*"):
            if f.suffix not in (".py", ".sol") or not f.is_file():
                continue
            live = "\n".join(l for l in f.read_text().split("\n")
                              if not l.lstrip().startswith(("//", "#")))
            names |= set(re.findall(r"function (test_\w+)", live))
            names |= set(re.findall(r"def (test_\w+)", live))
    return names


def check() -> int:
    """Every mutation still points at the code it guards, names tests that exist, and no id twice.

    A refactor moves a line and the mutation that guarded it stops matching anything. The full
    run says so, but the full run takes minutes and is called by hand, so a mutation can sit
    orphaned for days -- K7 and K10 did, from 23 to 24 Sep 2026, after their own author moved
    the lines they named. This check reads files and nothing else, so CI can afford it on every
    push: a mutation that matches no code, or matches twice, guards nothing either way.

    The names are checked here too, as of 1 October 2026, because the anchors alone were not
    enough: PG4 went on naming two tests after they were renamed in the same commit that renamed
    them, `--check` passed, and only the review bot noticed. A mutation naming a test that does
    not exist is reported SURVIVED by the full run whatever the code does -- it can never be
    killed, so it guards nothing while looking like it does.
    """
    problems = 0
    seen: dict[str, int] = {}
    known = _test_names()
    for mid, rel, old, _new, expected in MUTATIONS:
        seen[mid] = seen.get(mid, 0) + 1
        count = (ROOT / rel).read_text().count(old)
        if count != 1:
            print(f"{mid}: {count} matches in {rel}")
            problems += 1
        # Only the entries that are test names. Some mutations name a SENTENCE that has to stop
        # being true instead -- a page's wording, a document's claim -- and those are checked by
        # the run, not by a file listing.
        for name in expected:
            if re.fullmatch(r"test_\w+", name) and name not in known:
                print(f"{mid}: names {name}, which no test file defines")
                problems += 1
    for mid, times in sorted(seen.items()):
        if times > 1:
            print(f"{mid}: used {times} times")
            problems += 1
    if problems:
        print(f"mutations --check: {problems} mutation(s) guard nothing; fix the text or drop them")
        return 1
    print(f"mutations --check: {len(MUTATIONS)} mutations, each matching once")
    return 0


def run(selected: list[str]) -> int:
    unknown = sorted(set(selected) - {m[0] for m in MUTATIONS})
    if unknown:
        print(f"mutations: no such mutation: {', '.join(unknown)}")
        return 1
    chosen = [m for m in MUTATIONS if not selected or m[0] in selected]
    problems = baseline(chosen)
    if problems:
        print(f"mutations: {problems} problem(s) before mutating; nothing was mutated")
        return 1
    for mid, rel, old, new, expected in sorted(chosen, key=lambda m: (m[0][0] != "M", runner_of(m[0]), int(m[0][len(runner_of(m[0])):]))):
        cmd, pattern = RUNNERS[runner_of(mid)]
        path = ROOT / rel
        original = path.read_bytes()
        text = original.decode()
        count = text.count(old)
        if count != 1:
            print(f"{mid}: NOT APPLIED ({count} matches in {rel})")
            problems += 1
            continue
        path.write_text(text.replace(old, new), encoding="utf-8")
        try:
            try:
                proc = run_suite(cmd)
            except subprocess.TimeoutExpired:
                print(f"{mid}: TIMED OUT after {RUN_TIMEOUT_S}s")
                problems += 1
                continue
            out = proc.stdout + proc.stderr
            if "Compiler run failed" in out or "Error (" in out or "SyntaxError" in out:
                print(f"{mid}: DID NOT COMPILE")
                problems += 1
                continue
            red = failing_tests(out, pattern)
            missing = [t for t in expected if t not in red]
            if missing:
                print(f"{mid}: SURVIVED in {missing} (red: {sorted(red)})")
                problems += 1
            else:
                print(f"{mid}: killed by {expected}" + (f" (also red: {sorted(red - set(expected))})" if red - set(expected) else ""))
        finally:
            path.write_bytes(original)
    if problems:
        print(f"mutations: {problems} problem(s)")
        return 1
    print("mutations: every mutation applied and was caught")
    return 0


if __name__ == "__main__":
    if sys.argv[1:] == ["--check"]:
        sys.exit(check())
    sys.exit(run(sys.argv[1:]))
